package in.sevasetu.amc.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtFilter extends OncePerRequestFilter{private final TokenService tokens;public JwtFilter(TokenService tokens){this.tokens=tokens;}protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{var h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var u=tokens.verify(h.substring(7));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role()))));}catch(IllegalArgumentException ignored){}c.doFilter(r,s);}}
